List<String> args = new List<String>{'Ada', 'Lovelace'};
System.assertEquals('Hello Ada Lovelace', String.format('Hello {0} {1}', args));
System.assertEquals('Use {0} then Ada', String.format('Use ''{0}'' then {0}', args));
System.assertEquals('Lovelace/Ada/Lovelace/{2}', String.format('{1}/{0}/{1}/{2}', args));

